// Hand-authored — NOT generated by prism, and prism will not overwrite it
// (it only replaces files carrying its header). See the React wrapper for the
// reasoning: virtualization is the one case where the wrapper has to own the
// rows, because only Solid can create a Solid row.
import { createSignal, For, onCleanup, onMount, splitProps, type Component, type JSX } from 'solid-js';
import '@arclux/arc-ui/virtual-list';

declare module 'solid-js' {
  namespace JSX {
    interface IntrinsicElements {
      'arc-virtual-list': Record<string, unknown>;
    }
  }
}

export interface VirtualListProps {
  /** The full data array. Only the visible slice is rendered. */
  items: unknown[];
  /** Renders one row. Called only for rows currently on screen. */
  renderItem: (item: never, index: number) => JSX.Element;
  /** Row height in pixels. Must match what actually renders. */
  itemHeight?: number;
  /** Rows rendered above and below the viewport, to cover fast scrolling. */
  overscan?: number;
  /** Called when the visible range changes. `end` is exclusive. */
  onRangeChange?: (range: { start: number; end: number }) => void;
  class?: string;
  style?: string | JSX.CSSProperties;
  id?: string;
}

type ListElement = HTMLElement & {
  items?: unknown[];
  visibleRange?: { start: number; end: number };
};

export const VirtualList: Component<VirtualListProps> = (props) => {
  const [local, rest] = splitProps(props, [
    'items', 'renderItem', 'itemHeight', 'overscan', 'onRangeChange',
  ]);
  const [range, setRange] = createSignal({ start: 0, end: 0 });
  let el!: ListElement;

  onMount(() => {
    const onRangeChange = (e: Event) => {
      const { start, end } = (e as CustomEvent).detail;
      setRange({ start, end });
      local.onRangeChange?.({ start, end });
    };
    el.addEventListener('arc-range-change', onRangeChange);
    // The element may have measured before this ran, in which case its first
    // range event is already spent.
    if (el.visibleRange) setRange({ ...el.visibleRange });
    onCleanup(() => el.removeEventListener('arc-range-change', onRangeChange));
  });

  const indices = () => {
    const { start, end } = range();
    const out: number[] = [];
    for (let i = start; i < Math.min(end, local.items.length); i++) out.push(i);
    return out;
  };

  return (
    // `items` and `itemHeight` go through prop: — an array would stringify as
    // an attribute, and `itemHeight` lowercases to a name Lit ignores.
    <arc-virtual-list
      ref={el}
      prop:items={local.items}
      prop:itemHeight={local.itemHeight ?? 40}
      overscan={local.overscan ?? 5}
      {...rest}
    >
      <For each={indices()}>
        {(i) => <div slot={`item-${i}`}>{local.renderItem(local.items[i] as never, i)}</div>}
      </For>
    </arc-virtual-list>
  );
};
